using System.Globalization;
using Burdock.Server.Modules.Identity.Application;

namespace Burdock.Server.Modules.Identity.Domain;

/// <summary>
/// Server-side nickname generation (spec 09 §3.3.1, decision T10): «{Прикметник} Реп’ях #{NNNN}». The first ten
/// adjectives are the ones the app shows during onboarding, so a nickname generated by either side looks the same.
/// </summary>
public static class Nicknames
{
    public const string Noun = "Реп’ях";
    public const int MinTag = 1000;
    public const int MaxTagExclusive = 10000;

    public static IReadOnlyList<string> Adjectives { get; } =
    [
        "Хоробрий", "Уважний", "Веселий", "Кмітливий", "Допитливий", "Впертий", "Сонячний", "Меткий", "Спокійний", "Швидкий",
        "Бадьорий", "Відважний", "Вправний", "Дбайливий", "Дотепний", "Жвавий", "Завзятий", "Запальний", "Зіркий", "Лагідний",
        "Мудрий", "Наполегливий", "Невтомний", "Привітний", "Працьовитий", "Рішучий", "Сміливий", "Спритний", "Старанний", "Терплячий",
        "Уважливий", "Усміхнений", "Чемний", "Чуйний", "Щирий", "Яскравий", "Бравий", "Веселковий", "Дзвінкий", "Ранковий",
    ];

    public static string Compose(string adjective, int tag)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(adjective);
        ArgumentOutOfRangeException.ThrowIfLessThan(tag, MinTag);
        ArgumentOutOfRangeException.ThrowIfGreaterThanOrEqual(tag, MaxTagExclusive);
        return string.Create(CultureInfo.InvariantCulture, $"{adjective} {Noun} #{tag}");
    }

    public static string Generate(IRandomSource random)
    {
        ArgumentNullException.ThrowIfNull(random);
        return Compose(Adjectives[random.Next(0, Adjectives.Count)], random.Next(MinTag, MaxTagExclusive));
    }
}
